CustomField.formula:
IF(
  AND(Total_Units__c >= 8, Total_Units__c <= 22), 1,
  IF(
    AND(Total_Units__c >= 23, Total_Units__c <= 37), 2,
    IF(
      AND(Total_Units__c >= 38, Total_Units__c <= 52), 3,
      IF(
        AND(Total_Units__c >= 53, Total_Units__c <= 67), 4,
        IF(
          AND(Total_Units__c >= 68, Total_Units__c <= 82), 5,
          IF(
            AND(Total_Units__c >= 83, Total_Units__c <= 97), 6,
            IF(
              AND(Total_Units__c >= 98, Total_Units__c <= 112), 7,
              IF(
                Total_Units__c >= 113, 8,
                0
              )
            )
          )
        )
      )
    )
  )
)
